// Global Config (cogdef) - Pulling from Environment Variables
const config = {
  safeMode: $env.SAFE_MODE === 'true',
  logDrainId: $env.LOG_DRAIN_ID || "FEK7PNwR6I3XZygD",
  spreadsheetId: $env.SPREADSHEET_ID || "16dAe64XCQ_iecfAlrrdG5n6TtJyr2cDrMmIN4Uv9xBU",
  env: $env.NODE_ENV || "production",
  roiMins: 60
};

return $input.all().map(item => ({
  json: { 
    ...item.json,
    ...config,
    cogdef: config 
  }
}));

const aiResps = $input.all();
let clients = [];
try { clients = $('🛠️ MOCK: User Data').all(); } catch (e) {}
if (clients.length === 0 || !clients[0].json.clientEmail) {
  try { clients = $('📥 Fetch Completed Clients').all(); } catch (e) {}
}

return aiResps.map((aiResp, i) => {
  const client = clients[i]?.json || {};
  let email = {};
  try {
    const raw = aiResp.json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    email = JSON.parse(raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
  } catch (e) {
    email = {
      subject: `Project Completed: ${client.serviceRequired} for ${client.clientCompany} \ud83c\udfc6`,
      body: `Hi ${client.clientName},\n\nCongratulations! We have successfully completed the ${client.serviceRequired} project for ${client.clientCompany}. It has been a pleasure working with you.\n\nWe'd love to hear your feedback! Please take a moment to share your experience: https://forms.gle/sbZKjFkPS7bJ2enKA\n\nWe have now officially archived the project in our system. We look forward to our next collaboration!\n\nBest regards,\n${client.yourName}`
    };
  }

  const htmlBody = `<!DOCTYPE html><html><head><style>body{font-family:'Segoe UI',Tahoma,Geneva,Verdana,sans-serif;line-height:1.6;color:#1a202c;margin:0;padding:0;background-color:#f7fafc}.container{max-width:600px;margin:20px auto;border-radius:16px;overflow:hidden;background-color:#fff;box-shadow:0 10px 25px rgba(0,0,0,.1)}.header{background:linear-gradient(135deg,#f59e0b,#ef4444);color:#fff;padding:40px 20px;text-align:center}.content{padding:40px}.footer{background-color:#f8fafc;padding:20px;text-align:center;font-size:13px;color:#718096;border-top:1px solid #edf2f7}.confetti{font-size:40px;margin-bottom:20px}.button{display:inline-block;padding:14px 30px;background:linear-gradient(135deg,#f59e0b,#ef4444);color:#fff!important;text-decoration:none;border-radius:12px;font-weight:700;margin-top:25px}.highlight{color:#ea580c;font-weight:700}</style></head><body><div class="container"><div class="header"><div class="confetti">\ud83c\udf89</div><h1 style="margin:0;font-size:28px">Mission Accomplished!</h1><p style="margin:8px 0 0;font-size:16px;opacity:.9">Project Completion \u2014 ${client.clientCompany}</p></div><div class="content"><p style="font-size:18px">Hi <span class="highlight">${client.clientName}</span>,</p><p style="font-size:16px;color:#4a5568">${(email.body || '').replace(/\n/g, '<br>')}</p><div style="text-align:center;margin-top:30px"><p style="font-size:14px;color:#718096">We'd love to hear your feedback!</p><a href="https://forms.gle/sbZKjFkPS7bJ2enKA" class="button">Leave a Testimonial</a></div></div><div class="footer"><p>Sent by <strong>${client.agencyName}</strong></p><p style="margin-top:0">Cheers to ${client.clientCompany}'s continued growth!</p></div></div></body></html>`;

  return { json: { ...client, completionSubject: email.subject, completionBody: htmlBody } };
});
